<template>
	<d2-container>
		<div>
			<div v-if="nowView === 1">
				<div>
					<el-button type="primary" icon="el-icon-refresh" size="medium" @click="getTableData()">刷新
					</el-button>
					<!-- <el-button  type="success" icon="el-icon-circle-plus-outline" size="medium" @click="goToAdd()">新建</el-button>
					<el-button  type="danger" icon="el-icon-delete" size="medium" @click="deleteCginfo"
					 v-loading.fullscreen.lock="fullscreenLoading">删除</el-button> -->
					<el-button style="margin-left:10px;" type="success" icon="el-icon-s-check" size="medium" plain
						@click="shenhe()">审核</el-button>
					<el-button style="margin-left:10px;" type="danger" icon="el-icon-s-open" size="medium" plain
						@click="fanshen()">反审</el-button>
					<el-button type="info" icon="el-icon-download" size="medium" @click="exportDataEvent">导出</el-button>
					<!-- <el-button type="primary" icon="el-icon-printer" size="medium"  @click="dialogTableVisible = true">打印</el-button> -->
					<!-- 	 <el-button type="primary" icon="el-icon-printer" size="medium"  @click="ceshi">打印2</el-button> -->
					<el-input style="margin-left:30px;width: 150px;" size="medium" placeholder="输入客户ID"
						v-model="searchFilter.name" clearable v-show="false"></el-input>
					<el-select v-model="searchFilter.name" filterable placeholder="选择客户名称"
						style="margin-left:30px;width: 150px;" size="medium">
						<el-option v-for="item in khList" :key="item.value" :label="item.客户名称" :value="item.客户ID">
						</el-option>
					</el-select>
					<el-autocomplete style="margin-left:5px;width: 80px;" class="inline-input"
						v-model="searchFilter.disable" :fetch-suggestions="querySearch" placeholder="审核？"
						size="medium"></el-autocomplete>
					<el-date-picker style="margin-left:5px;margin-top:10px;width: 150px;" size="medium"
						v-model="searchFilter.riqi" type="date" placeholder="选择日期" value-format="yyyy-MM-dd">
					</el-date-picker>
					<!-- 	 <el-input style="margin-left:10px;width: 150px;" size="medium" placeholder="搜索账号" v-model="searchFilter.account"
					 clearable></el-input> 
					 <el-autocomplete style="margin-left:10px;width: 80px;" v-model="searchFilter.disable" :fetch-suggestions="querySearch"
					 clearable placeholder="停用" size="medium"></el-autocomplete>  -->
					<el-button style="margin-left:5px; margin-top:10px;" type="primary" icon="el-icon-search"
						size="medium" plain @click="handleSearch">搜索</el-button>
					<el-button style="margin-top:10px;" type="primary" icon="el-icon-zoom-out" size="medium" plain
						@click="clearFilter()">清空条件</el-button>
				</div>

				<vxe-table style="margin-top: 10px;" border stripe resizable highlight-hover-row highlight-current-row
					align="center" @cell-dblclick="tabs = true" :height="tableHeight" :loading="loading" row-id="id"
					:print-config="{}" :data="tableData"
					:expand-config="{ accordion: true, iconOpen: 'fa fa-minus-square', iconClose: 'fa fa-plus-square', toggleMethod: toggleExpandMethod }"
					ref="xTable1" id="dy1">
					<vxe-table-column type="checkbox" width="60"></vxe-table-column>
					<!-- <vxe-table-column  title="操作" width="80">
						<template v-slot="{ row }">
							<el-button type="warning" plain size="small" @click="goToEdit(row)">编辑</el-button>
						</template>
</vxe-table-column> -->
					<vxe-table-column type="expand" width="50" title="展开">
						<template #content="{}">
							<div class="expand-wrapper">

								<vxe-table border highlight-hover-row highlight-current-row align="center"
									:data="childData">
									<vxe-table-column type="seq" width="50" title="序号"></vxe-table-column>
									<vxe-column field='单据编号' title='单据编号'></vxe-column>
									<vxe-column field="产品ID" title="产品ID" :visible="false"></vxe-column>
									<vxe-column field="产品名称" title="产品名称"></vxe-column>
									<vxe-column field="型号" title="型号"></vxe-column>
									<vxe-column field="规格" title="规格"></vxe-column>
									<vxe-column field="单位" title="单位"></vxe-column>
									<vxe-column field="单价" title="单价" width="110"></vxe-column>
									<vxe-column field="数量" title="数量" width="110"></vxe-column>
									<vxe-column field="金额" title="金额" width="110">
										<template #default="{ row }">
											<span>{{ row.单价 * row.数量 }}</span>
										</template>
									</vxe-column>
									<!-- <vxe-column field="货位号" title="货位号" width="110"></vxe-column> -->
									<vxe-column field="状态" title="审核">
										<template #default="{ row }">
											<el-tag v-if="row.状态 === null" type="warning" size="medium "> 未审核</el-tag>
											<el-tag v-else-if="row.状态 === 0" type="warning"
												size="medium ">未审核</el-tag>
											<el-tag v-else type="success" size="medium "> 已审核 </el-tag>
										</template>
									</vxe-column>
									<!-- <vxe-table-column  title="操作" width="80">
						<template v-slot="{ row }">
							<el-button type="danger" plain size="small" @click="goToEdit(row)">删除</el-button>
						</template>
					</vxe-table-column> -->
								</vxe-table>
							</div>
						</template>
					</vxe-table-column>
					<vxe-table-column type="seq" width="50" title="序号"></vxe-table-column>
					<vxe-table-column field="id" title="id" :visible="false"></vxe-table-column>
					<vxe-table-column field="单据编号" title="单据编号"></vxe-table-column>
					<vxe-table-column field="客户ID" title="客户ID" width="80" :visible="false"></vxe-table-column>
					<vxe-table-column field="客户名称" title="客户名称"></vxe-table-column>
					<vxe-table-column field="业务员" title="业务员" width="80"></vxe-table-column>
					<vxe-table-column field="总金额" title="总金额"></vxe-table-column>
					<vxe-table-column field="付款方式" title="付款方式" width="80"></vxe-table-column>
					<vxe-table-column field="日期" title="日期"></vxe-table-column>
					<vxe-column field="状态" title="审核" width="90">
						<template #default="{ row }">
							<el-tag v-if="row.状态 === null" type="warning" size="medium "> 未审核</el-tag>
							<el-tag v-else-if="row.状态 === 0" type="warning" size="medium ">未审核</el-tag>
							<el-tag v-else type="success" size="medium "> 已审核 </el-tag>
						</template>
					</vxe-column>
					<!-- <vxe-table-column field="类型" title="类型"  width="100"></vxe-table-column>  -->
				</vxe-table>
				<vxe-pager :loading="loading" :current-page="tablePage.currentPage" :page-size="tablePage.pageSize"
					:total="tablePage.totalResult"
					:layouts="['PrevPage', 'JumpNumber', 'NextPage', 'FullJump', 'Sizes', 'Total']"
					@page-change="handlePageChange">
				</vxe-pager>
				<el-dialog :visible.sync="dialogTableVisible" width="65%" @opened="printEvent1">
					<div slot="title" class="dialog-footer">
						<el-button @click="dialogTableVisible = false">取 消</el-button>
						<el-button type="primary" @click="printEvent1">打 印</el-button>
						<!-- <div id="myPrint6">           
            <p>将当前渲染的<span style="color: #20f320">内容</span>打印出来，仅<span style="color: blue;font-size: 20px">打印</span>内联<span style="color: red">样式</span></p>
            <p>内容<span style="font-size: 30px;font-weight: 700">区域</span></p>
          </div> -->
					</div>
					<div ref="print" id="myPrint5" media='print' style='font-family:\\5B8B\\4F53'>
						<div v-for="(item, index) in tableData" :key="index" v-show="isShow">
							<div v-if="index % 3 == 0" ref="print2">
								<div style='width:60%;margin:0 auto;text-align: center;'>
									<h1 style='padding: 12px 0px 34px 0;' id="djmz">采购单</h1>
									<!-- <div style='float:right;    font-size: 14px;font-weight: 800;'>页码:{{(index+3)/3}}/{{Math.ceil(tableData.length/3)}}</div> -->
								</div>

								<table border='0' style='width:100%;' id='printtable1'>
									<tr height='30px;'>
										<td style='text-align:left;'>入库单号：<span id=''>{{ item.id }}</span></td>
										<td style='text-align:center;'>单位名称：<span id=''>{{ item.住址 }}</span></td>
									</tr>
								</table>
								<table border='1' style='width:100%; display:inline-table;border-collapse: collapse;'
									id='printtable2'>
									<tr height='40px;'>
										<td style='text-align:center;width:10%'>序号</td>
										<td style='text-align:center;width:20%'>姓名</td>
										<td style='text-align:center;width:20%'>联系方式</td>
										<td style='text-align:center;width:20%'>照片</td>
										<td style='text-align:center;width:30%'>住址</td>
									</tr>
									<tr height='40px;' v-for="(ite, ind) in tableData.slice(index, index + 3)" :key="ind">
										<td style='text-align:center;'>{{ ind }}</td>
										<td style='text-align:center;'>{{ ite.用户名 }}</td>
										<td style='text-align:center;'>{{ ite.联系方式 }}</td>
										<td style='text-align:center;'>{{ ite.照片 }}</td>
										<td style='text-align:center;'>{{ ite.住址 }}</td>
									</tr>
								</table>
								<table border='0' style='width:100%;' id='printtable4'>
									<tr height='30px;'>
										<td style='text-align:left;'>页码:<span
												id=''>{{ (index + 3) / 3 }}/{{ Math.ceil(tableData.length / 3) }}</span></td>
										<td style='text-align:center;'><span id=''></span></td>
										<td style='text-align:right;'>金额合计(大写):</td>
										<!-- <td style='text-align:left;'>&nbsp;<span id=''>{{setter.ToString(zje.toFixed(2))}}</span></td>  -->
										<!-- <td style='text-align:center;'>￥:&nbsp;<span id=''>{{}}</span></td>  -->
									</tr>
								</table>
								<table border='0' style='width:100%;' id='printtable3'>
									<tr height='30px;'>
										<td style='text-align:left;'>制单：<span id=''>{{ item.id }}</span></td>
										<td style='text-align:center;'>保管员：<span id=''>{{ item.用户名 }}</span></td>
										<td style='text-align:right;'>入库日期：<span id=''>{{ item.照片 }}</span></td>
									</tr>
								</table>


								<div style='page-break-after:always;'></div>
							</div>
						</div>
					</div>
				</el-dialog>
			</div>

			<!-- <div v-if="nowView===2">
				<CgEdit :passID="passID" :authKeys="authKeys" @goBack="goBack" ></CgEdit>
			</div> -->
			<el-drawer style="margin-top:30px;" :visible.sync="tabs" direction="rtl" custom-class="demo-drawer"
				ref="drawer" @opened="hangsj()" @closed="tqqh()" size="30%">
				<el-tabs v-model="activeName" @tab-click="handleClick">
					<el-tab-pane label="审核情况" name="first">
						<div class="demo-drawer__content">
							<el-form ref="form" :model="form2">
								<el-form-item label="审核意见" style="margin-left:10px;margin-right:10px;">
									<el-input type="textarea" :rows="5" v-model="form2.shsm"></el-input>
								</el-form-item>
								<el-form-item label="审核通过" style="margin-left:10px;">
									<el-switch v-model="form2.shqk"></el-switch>
								</el-form-item>
								<el-form-item>
									<el-button type="primary" @click="onSubmit" size="mini"
										style="margin-left:10px;">确定</el-button>
									<el-button @click="tabs = false" size="mini">取消</el-button>
								</el-form-item>
							</el-form>
						</div>
					</el-tab-pane>
					<el-tab-pane label="审核历史" name="second">
						<div class="block" style="margin-left:10px;margin-right:10px; margin-bottom:10px;">
							<div class="radio">
								排序：
								<el-radio-group v-model="reverse">
									<el-radio :label="true">倒序</el-radio>
									<el-radio :label="false">正序</el-radio>
								</el-radio-group>
							</div>

							<el-timeline :reverse="reverse">
								<el-timeline-item v-for="(val, index) in shendata" :key="index" :timestamp="val.time">
									<span v-html="val.str">{{val.str}}</span>
								</el-timeline-item>
							</el-timeline>
						</div>
					</el-tab-pane>
				</el-tabs>
			</el-drawer>


		</div>
	</d2-container>

</template>
<script>
import printJS from 'print-js'
import { mapState, mapActions } from 'vuex'
import setter from '@/libs/setter.js'
//import Print from './plugin/print/Print'
import {
	GetMenuTreeOnAuth,
} from '@api/sys.login.js'
import {
	Query,
	Aud
} from '@api/shuju.js'

export default {
	name: 'ShenSh',
	/* components: {
		CgEdit,
	}, */
	data() {
		return {
			fullscreenLoading: false,
			nowView: 1, //当前视图：1是列表，2是编辑页面
			authKeys: [], //用户的权限数组
			tableHeight: 0, //表格高度
			tableData: [], //表内数据	相当于layuidata	
			childData: [],	//子表数据	相当于soulTable子表		
			loading: false, //是否显示加载中
			tablePage: { // 分页属性---
				currentPage: 1, //当前页 相当于layui的page
				pageSize: 10,  	//每页条数 相当于layui的limt
				totalResult: 0  //总页数   相当于count				
			},
			isShow: true,
			tabs: false,
			TFList: [{
				label: '是',
				value: true
			},
			{
				label: '否',
				value: false
			}
			],
			djlx: '',
			pid: '',
			ztz: 0,
			sfsh: '否',
			reverse: true,
			shendata: [],
			gnqx: [],
			activeName: 'first',
			uname: '',
			dwMc: '',
			khList: [],
			cpList: [],
			//搜索变量
			searchFilter: {
				name: '',
				//account: '',
				disable: '否',
				riqi: '',
			},
			disables: [{
				'value': '是'
			}, {
				'value': '否'
			}],

			dialogTableVisible: false,
			passID: null,

			form2: {
				shqk: true,
				shsm: '',
			},
			//批量复制权限
			authCopy: {
				dialogVisible: false,
				userOptions: [],
				form: {
					selectUserID: ''
				},
				rules: {
					selectUserID: [{
						required: true,
						message: '请选择用户',
						trigger: 'change'
					}]
				}
			},

		}
	},
	created() {
		this.dqy()
		this.getAuthKeys()
		this.getkhData()
		this.getcpData()

	},
	mounted() {
		this.autoTableHeight()
	},

	methods: {

		//表格根据浏览器调整高度---
		autoTableHeight() {
			console.log(this.$route.query.lx)
			this.tableHeight = window.innerHeight - 235;
			window.onresize = () => {
				return (() => {
					this.tableHeight = window.innerHeight - 235;
				})();
			};
		},
		getkhData() {
			Query({
				tj: true,
				tablename: '客户',
				field: 'id'
			})
				.then(res => {
					//this.tableData = res.data()
					//console.log(res.data)
					this.khList = res.data
				})
				.catch(err => {
					// 异常情况

				})
		},
		getcpData() {
			Query({
				tj: true,
				tablename: '产品',
				field: 'id'
			})
				.then(res => {
					//this.tableData = res.data()
					//console.log(res.data)
					this.cpList = res.data
				})
				.catch(err => {
					// 异常情况

				})
		},
		getAuthKeys() {
			let sj = JSON.parse(window.localStorage.getItem('d2admin-1.7.2'))
			let info = sj.sys.user.用户.user.info
			if (info.name == 'admin') {
				let qx;
				Query({
					tablename: '菜单',
					columns: '二级菜单',
					field: 'id',
					tj: true,
				})
					.then(resl => {
						qx = resl.map(function (v,) {
							return v.二级菜单
						})
						console.log(qx);
						this.authKeys = qx
						this.getTableData()
						this.uname = info.name
					}).catch(err => { })
			} else {
				GetMenuTreeOnAuth({
					username: info.name
				})
					.then(res => {
						this.authKeys = res.功能权限
						console.log(this.authKeys);
						this.getTableData()
						this.uname = info.name

					})
					.catch(err => { })
			}
		},
		getTableData() {
			let dqy = this.$store.state.d2admin.page.current
			console.log(dqy)
			let tj
			/* if(dqy == '/ShenCai?lx=cg'){
			   tj = `类型 = '采购入库'`
			}else if(dqy == '/ShenCai?lx=gt'){
				tj = `类型 = '采购退出'`
			}
			 */
			tj = `类型 = '销售出库'`
			let tjx
			let tjy
			let tjz
			//tj = `类型 = '采购入库'`
			//let ss 
			//if (this.authKeys.indexOf('消息通知') > -1) {
			this.loading = true
			if (this.$route.query.lx == 'sh') {
				console.log('(状态 IS NULL OR 状态 = 0)')
			} else if (this.$route.query.lx != 'sh') {
				console.log(true)
			}
			if (this.searchFilter.name != '' && this.searchFilter.name != null) {
				tjx = `客户ID= '${this.searchFilter.name}'`
				tj = tj + ' and ' + tjx
			} else {
				tjx = true
				tj = tj + ' and ' + tjx
			}
			if (this.searchFilter.disable == '否') {
				tjy = '(状态 IS NULL OR 状态 = 0)'
				tj += ' and ' + tjy
			} else if (this.searchFilter.disable == '是') {
				tjy = '状态=-1'
				tj += ' and ' + tjy
			}
			if (this.searchFilter.riqi) {
				console.log(this.searchFilter.riqi)
				tjz = `日期 in ('${this.searchFilter.riqi}')`
				tj += ' and ' + tjz
			}
			Query({
				//pageSize: this.tablePage.pageSize,//每页条数 相当于layui的limit
				//currentPage: this.tablePage.currentPage, // 相当于layui的page
				//searchFilter: this.searchFilter  
				limit: this.tablePage.pageSize,
				page: this.tablePage.currentPage,
				tj: tj,
				tablename: '销售',
				field: 'id',
				order: 'desc',
			})
				.then(res => {
					let khsj = this.khList
					let ss = res.data.map(function (v, i) {
						let obj4 = khsj.find(o => o.客户ID === v.客户ID);
						console.log(obj4.客户名称)
						//this.dwMc = obj4.客户名称
						delete obj4.id;
						delete obj4.日期;
						return Object.assign(v, obj4);
					});
					console.log(ss)
					this.tableData = ss
					this.tablePage.totalResult = res.count
					this.loading = false


				})
				.catch(err => {
					// 异常情况
					this.loading = false
				})
			//}

		},
		toggleExpandMethod({ expanded, row }) {
			if (expanded) {
				console.log(row.单据编号)
				let tj = '单据编号' + "=" + '"' + row.单据编号 + '"';
				Query({
					tj: tj,
					tablename: '出单',
					field: 'id'
				})
					.then(res => {
						let cpsj = this.cpList
						let ssy = res.data.map(function (v, i) {
							let obj5 = cpsj.find(o => o.产品ID === v.产品ID);
							delete obj5.id;
							delete obj5.日期;
							return Object.assign(v, obj5);
						});
						console.log(ssy)
						this.childData = ssy
					})
					.catch(err => {
						// 异常情况

					})
			}
			return true
		},

		shenhe() {
			this.ztz = -1
			this.dlsh()
		},
		fanshen() {
			this.ztz = 0
			this.dlsh()
		},
		handleSearch() {
			this.tablePage.currentPage = 1 //注意要回来第一页
			this.getTableData()
		},
		handlePageChange({
			currentPage,
			pageSize
		}) {
			this.tablePage.currentPage = currentPage
			this.tablePage.pageSize = pageSize
			this.getTableData()
		},
		clearFilter() {
			let obj = this.searchFilter
			for (let key in obj) {
				this.searchFilter
				obj[key] = null
			}
		},

		exportDataEvent() {
			this.$refs.xTable1.exportData({
				type: 'csv'
			})
		},

		//用户采购
		deleteCginfo() {
			let _this = this
			let selectRecords = this.$refs.xTable1.getCheckboxRecords()
			let tempIDs = []
